const rows = $input.all().map(i => i.json);
if (rows.length !== 2) throw new Error(`expected_2_rows_got_${rows.length}`);
const byEvent = Object.fromEntries(rows.map(r => [r.eventKey, r]));
const a = byEvent['event:p1'];
const b = byEvent['event:p3'];
if (!a || !b) throw new Error('expected_event_p1_and_p3');
if (a.identityKey !== 'email:persist@test.example') throw new Error(`bad_email_identity_${a.identityKey}`);
if (a.recordId !== 'lead:p1') throw new Error(`bad_record_p1_${a.recordId}`);
if (b.identityKey !== 'phone:+34600999111') throw new Error(`bad_phone_identity_${b.identityKey}`);
if (b.recordId !== 'lead:p3') throw new Error(`bad_record_p3_${b.recordId}`);
return [{json:{pass:true, rows:rows.length, events:rows.map(r=>r.eventKey).sort(), identities:rows.map(r=>r.identityKey).sort(), persistence:'n8n-data-table'}}];
